def isPossible(N, P, prerequisites):
    adj = [[] for _ in range(N)]
    indegree = [0] * N

    for u, v in prerequisites:
        adj[v].append(u)
        indegree[u] += 1

    queue = []
    for i in range(N):
        if indegree[i] == 0:
            queue.append(i)

    count = 0
    idx = 0
    while idx < len(queue):
        node = queue[idx]
        idx += 1
        count += 1

        for neighbor in adj[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return count == N
